<script>document.addEventListener('DOMContentLoaded',()=>{const farm=document.querySelector('#harvest-farm'),product=document.querySelector('#harvest-product'),unit=document.querySelector('#harvest-unit');if(!farm||!product||!unit)return;const sync=()=>{for(const option of product.options){if(!option.value)continue;option.hidden=option.dataset.farm!==farm.value;if(option.hidden&&option.selected)product.value='';}if(unit.dataset.custom!=='1'&&product.selectedOptions[0]?.dataset.unit)unit.value=product.selectedOptions[0].dataset.unit;};farm.addEventListener('change',sync);product.addEventListener('change',()=>{unit.dataset.custom='0';sync();});unit.addEventListener('input',()=>{unit.dataset.custom='1';});sync();});document.addEventListener("DOMContentLoaded",()=>{const form=document.querySelector("form[data-today]"),start=document.querySelector("#harvest-starts-at"),end=document.querySelector("#harvest-ends-at");if(!form||!start||!end)return;const later=(a,b)=>a>b?a:b;start.addEventListener("change",()=>{end.min=later(form.dataset.today,start.value);if(end.value<end.min)end.value=end.min;});form.addEventListener("submit",e=>{const msg=start.value<form.dataset.today&&start.value!==form.dataset.originalStart?"La date de début doit être la date du jour ou une date future.":end.value<form.dataset.today&&end.value!==form.dataset.originalEnd?"La date de fin doit être la date du jour ou une date future.":end.value<start.value?"La date de fin doit être postérieure ou égale à la date de début.":"";if(msg){e.preventDefault();window.alert(msg);}});});</script>
